result = 0
for i in range(len(operator) - 1):
    op = operator[i]
    num1 = operand[i]
    num2 = operand[i + 1]
    if op == '+':
        result += num1 + num2
    elif op == '-':
        result -= num1 + num2
    elif op == '*':
        result *= num1 + num2
    elif op == '/':
        result //= num1 + num2
    elif op == '**':
        result **= num1 + num2
return result

